              <Spinner />
              <p className="text-md font-serif text-gray-600 mt-4">Loading Model...</p>
            </div>
        )}

        <AnimatePresence>
          {isLoading && (
              <motion.div
                  className="absolute inset-0 bg-white/80 backdrop-blur-md flex flex-col items-center justify-center z-20 rounded-lg"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
              >
                  <Spinner />
                  {loadingMessage && (
                      <p className="text-lg font-serif text-gray-700 mt-4 text-center px-4">{loadingMessage}</p>
                  )}
              </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Prompt Bar and Pose Controls */}
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-30 flex flex-col items-center gap-4 w-full max-w-xl px-4">

        {/* Remix / Edit Prompt Input */}
        <AnimatePresence>
            {displayImageUrl && !isLoading && (
                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="w-full flex flex-col gap-2"
                >
                    <div className="flex flex-wrap justify-center gap-2 mb-1">
                        {QUICK_EDITS.map((edit) => (
                            <button
                                key={edit.label}
                                onClick={() => onEditImage(edit.prompt)}
                                className="text-[10px] uppercase tracking-wider font-bold bg-white/40 hover:bg-white/80 backdrop-blur-md text-gray-700 px-3 py-1 rounded-full border border-gray-300/50 transition-all"
                            >
                                {edit.label}
                            </button>
                        ))}
                    </div>
                    <form onSubmit={handleEditSubmit} className="relative w-full shadow-xl rounded-2xl overflow-hidden border border-gray-200/50 bg-white/70 backdrop-blur-xl">
                        <input 
                            type="text" 
                            placeholder="Type an edit prompt (e.g. 'Add a retro filter')" 
                            value={editPrompt}
                            onChange={(e) => setEditPrompt(e.target.value)}
                            className="w-full pl-5 pr-12 py-4 bg-transparent focus:outline-none text-sm text-gray-800"
                        />
                        <button 
                            type="submit"
                            disabled={!editPrompt.trim() || isLoading}
                            className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-xl bg-gray-900 text-white disabled:bg-gray-200 transition-colors"
                        >
                            <ShirtIcon className="w-5 h-5" />
                        </button>
                    </form>
                </motion.div>
            )}
        </AnimatePresence>

        {/* Pose Controls */}
        {displayImageUrl && !isLoading && (
            <div 
            className="opacity-0 group-hover:opacity-100 transition-opacity duration-300"
            onMouseEnter={() => setIsPoseMenuOpen(true)}
            onMouseLeave={() => setIsPoseMenuOpen(false)}
            >
            <AnimatePresence>
                {isPoseMenuOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2, ease: "easeOut" }}
                        className="absolute bottom-full mb-3 w-64 bg-white/80 backdrop-blur-lg rounded-xl p-2 border border-gray-200/80 shadow-lg"
                    >
                        <div className="grid grid-cols-2 gap-2">
                            {poseInstructions.map((pose, index) => (
                                <button
                                    key={pose}
                                    onClick={() => onSelectPose(index)}
                                    disabled={isLoading || index === currentPoseIndex}
                                    className="w-full text-left text-sm font-medium text-gray-800 p-2 rounded-md hover:bg-gray-200/70 disabled:opacity-50 disabled:bg-gray-200/70 disabled:font-bold disabled:cursor-not-allowed"
                                >
                                    {pose}
                                </button>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="flex items-center justify-center gap-2 bg-white/60 backdrop-blur-md rounded-full p-2 border border-gray-300/50 shadow-sm">
                <button 
                onClick={handlePreviousPose}
                aria-label="Previous pose"
                className="p-2 rounded-full hover:bg-white/80 active:scale-90 transition-all disabled:opacity-50"
                disabled={isLoading}
