                <span className="text-sm font-semibold text-gray-800 w-48 text-center truncate px-2" title={poseInstructions[currentPoseIndex]}>
                {poseInstructions[currentPoseIndex]}
                </span>
                <button 
                onClick={handleNextPose}
                aria-label="Next pose"
                className="p-2 rounded-full hover:bg-white/80 active:scale-90 transition-all disabled:opacity-50"
                disabled={isLoading}
                >
                <ChevronRightIcon className="w-5 h-5 text-gray-800" />
                </button>
            </div>
            </div>
        )}
      </div>
    </div>
  );
};

