interface CanvasProps {
  displayImageUrl: string | null;
  onStartOver: () => void;
  isLoading: boolean;
  loadingMessage: string;
  onSelectPose: (index: number) => void;
  poseInstructions: string[];
  currentPoseIndex: number;
  availablePoseKeys: string[];
  isSharpened: boolean;
  onToggleSharpen: () => void;
  onEditImage: (prompt: string) => void;
  onUpscale: () => void;
  onSaveOutfit: () => void;
}

const QUICK_EDITS = [
    { label: "Retro Filter", prompt: "Add a warm, grainy 90s retro film filter to the entire image." },
    { label: "Clean Background", prompt: "Remove the person in the background and clean up the scene." },
    { label: "Cyberpunk", prompt: "Change the background to a neon cyberpunk city street at night." },
    { label: "Vogue Cover", prompt: "Make it look like a high-end Vogue magazine cover with elegant typography." },
];

const Canvas: React.FC<CanvasProps> = ({ 
  displayImageUrl, 
  onStartOver, 
  isLoading, 
  loadingMessage, 
  onSelectPose, 
  poseInstructions, 
  currentPoseIndex, 
  availablePoseKeys,
  isSharpened,
  onToggleSharpen,
  onEditImage,
  onUpscale,
  onSaveOutfit
}) => {
  const [isPoseMenuOpen, setIsPoseMenuOpen] = useState(false);
  const [editPrompt, setEditPrompt] = useState("");

  const handlePreviousPose = () => {
    if (isLoading || availablePoseKeys.length <= 1) return;

    const currentPoseInstruction = poseInstructions[currentPoseIndex];
    const currentIndexInAvailable = availablePoseKeys.indexOf(currentPoseInstruction);

    if (currentIndexInAvailable === -1) {
        onSelectPose((currentPoseIndex - 1 + poseInstructions.length) % poseInstructions.length);
        return;
    }

    const prevIndexInAvailable = (currentIndexInAvailable - 1 + availablePoseKeys.length) % availablePoseKeys.length;
    const prevPoseInstruction = availablePoseKeys[prevIndexInAvailable];
    const newGlobalPoseIndex = poseInstructions.indexOf(prevPoseInstruction);

    if (newGlobalPoseIndex !== -1) {
        onSelectPose(newGlobalPoseIndex);
    }
  };

  const handleNextPose = () => {
    if (isLoading) return;

    const currentPoseInstruction = poseInstructions[currentPoseIndex];
    const currentIndexInAvailable = availablePoseKeys.indexOf(currentPoseInstruction);

    if (currentIndexInAvailable === -1 || availablePoseKeys.length === 0) {
        onSelectPose((currentPoseIndex + 1) % poseInstructions.length);
        return;
    }

    const nextIndexInAvailable = currentIndexInAvailable + 1;
    if (nextIndexInAvailable < availablePoseKeys.length) {
        const nextPoseInstruction = availablePoseKeys[nextIndexInAvailable];
        const newGlobalPoseIndex = poseInstructions.indexOf(nextPoseInstruction);
        if (newGlobalPoseIndex !== -1) {
            onSelectPose(newGlobalPoseIndex);
        }
    } else {
        const newGlobalPoseIndex = (currentPoseIndex + 1) % poseInstructions.length;
        onSelectPose(newGlobalPoseIndex);
    }
  };

  const handleEditSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (editPrompt.trim() && !isLoading) {
        onEditImage(editPrompt);
        setEditPrompt("");
    }
  };

  return (
    <div className="w-full h-full flex items-center justify-center p-4 relative animate-zoom-in group">
      {/* Hidden SVG Filter for Sharpening */}
      <svg width="0" height="0" style={{ position: 'absolute', pointerEvents: 'none' }}>
        <defs>
          <filter id="sharpen-filter">
            <feConvolveMatrix 
              order="3" 
              preserveAlpha="true" 
              kernelMatrix="0 -1 0 -1 5 -1 0 -1 0"
            />
          </filter>
        </defs>
      </svg>

      {/* Top Left Controls */}
      <div className="absolute top-4 left-4 z-30 flex flex-col gap-2">
        <button 
            onClick={onStartOver}
            className="flex items-center justify-center text-center bg-white/60 border border-gray-300/80 text-gray-700 font-semibold py-2 px-4 rounded-full transition-all duration-200 ease-in-out hover:bg-white hover:border-gray-400 active:scale-95 text-sm backdrop-blur-sm shadow-sm"
        >
            <RotateCcwIcon className="w-4 h-4 mr-2" />
            Start Over
        </button>

        <button 
            onClick={onToggleSharpen}
            className={`flex items-center justify-center text-center border font-semibold py-2 px-4 rounded-full transition-all duration-200 ease-in-out active:scale-95 text-sm backdrop-blur-sm ${
              isSharpened 
              ? 'bg-indigo-600 border-indigo-700 text-white shadow-lg' 
              : 'bg-white/60 border-gray-300/80 text-gray-700 hover:bg-white hover:border-gray-400 shadow-sm'
            }`}
            title={isSharpened ? "Disable Sharpening" : "Enable Sharpening"}
        >
            <WandIcon className={`w-4 h-4 mr-2 ${isSharpened ? 'text-indigo-100' : 'text-gray-500'}`} />
            {isSharpened ? 'Sharpened' : 'Sharpen Image'}
        </button>

        <button 
            onClick={onUpscale}
            disabled={isLoading}
            className="flex items-center justify-center text-center bg-gradient-to-r from-amber-400 to-orange-500 text-white font-bold py-2 px-4 rounded-full transition-all duration-200 ease-in-out hover:from-amber-500 hover:to-orange-600 active:scale-95 text-sm shadow-lg disabled:opacity-50 disabled:cursor-not-allowed"
            title="Upscale to 4K"
        >
            <SparklesIcon className="w-4 h-4 mr-2 text-white" />
            Upscale to 4K
        </button>
      </div>

      {/* Top Right Controls */}
      <div className="absolute top-4 right-4 z-30">
        <button 
            onClick={onSaveOutfit}
            disabled={isLoading || !displayImageUrl}
            className="flex items-center justify-center bg-white border border-gray-200 text-gray-800 font-bold p-3 rounded-full transition-all duration-200 ease-in-out hover:bg-indigo-50 hover:border-indigo-200 active:scale-90 text-sm shadow-md disabled:opacity-50 disabled:cursor-not-allowed"
            title="Save Outfit to Collection"
        >
            <BookmarkIcon className="w-6 h-6 text-indigo-600" />
        </button>
      </div>

      {/* Image Display or Placeholder */}
      <div className="relative w-full h-full flex items-center justify-center">
        {displayImageUrl ? (
          <img
            key={displayImageUrl} 
            src={displayImageUrl}
            alt="Virtual try-on model"
            style={{ filter: isSharpened ? 'url(#sharpen-filter)' : 'none' }}
            className="max-w-full max-h-full object-contain transition-opacity duration-500 animate-fade-in rounded-lg shadow-2xl"
          />
        ) : (
            <div className="w-[400px] h-[600px] bg-gray-100 border border-gray-200 rounded-lg flex flex-col items-center justify-center">
              <Spinner />
              <p className="text-md font-serif text-gray-600 mt-4">Loading Model...</p>
            </div>
        )}

        <AnimatePresence>
          {isLoading && (
              <motion.div
                  className="absolute inset-0 bg-white/80 backdrop-blur-md flex flex-col items-center justify-center z-20 rounded-lg"
                  initial={{ opacity: 0 }}
                  animate={{ opacity: 1 }}
                  exit={{ opacity: 0 }}
              >
                  <Spinner />
                  {loadingMessage && (
                      <p className="text-lg font-serif text-gray-700 mt-4 text-center px-4">{loadingMessage}</p>
                  )}
              </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* Prompt Bar and Pose Controls */}
      <div className="absolute bottom-6 left-1/2 -translate-x-1/2 z-30 flex flex-col items-center gap-4 w-full max-w-xl px-4">

        {/* Remix / Edit Prompt Input */}
        <AnimatePresence>
            {displayImageUrl && !isLoading && (
                <motion.div 
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="w-full flex flex-col gap-2"
                >
                    <div className="flex flex-wrap justify-center gap-2 mb-1">
                        {QUICK_EDITS.map((edit) => (
                            <button
                                key={edit.label}
                                onClick={() => onEditImage(edit.prompt)}
                                className="text-[10px] uppercase tracking-wider font-bold bg-white/40 hover:bg-white/80 backdrop-blur-md text-gray-700 px-3 py-1 rounded-full border border-gray-300/50 transition-all"
                            >
                                {edit.label}
                            </button>
                        ))}
                    </div>
                    <form onSubmit={handleEditSubmit} className="relative w-full shadow-xl rounded-2xl overflow-hidden border border-gray-200/50 bg-white/70 backdrop-blur-xl">
                        <input 
                            type="text" 
                            placeholder="Type an edit prompt (e.g. 'Add a retro filter')" 
                            value={editPrompt}
                            onChange={(e) => setEditPrompt(e.target.value)}
                            className="w-full pl-5 pr-12 py-4 bg-transparent focus:outline-none text-sm text-gray-800"
                        />
                        <button 
                            type="submit"
                            disabled={!editPrompt.trim() || isLoading}
                            className="absolute right-2 top-1/2 -translate-y-1/2 p-2 rounded-xl bg-gray-900 text-white disabled:bg-gray-200 transition-colors"
                        >
                            <ShirtIcon className="w-5 h-5" />
                        </button>
                    </form>
                </motion.div>
            )}
        </AnimatePresence>

        {/* Pose Controls */}
        {displayImageUrl && !isLoading && (
            <div 
            className="opacity-0 group-hover:opacity-100 transition-opacity duration-300"
            onMouseEnter={() => setIsPoseMenuOpen(true)}
            onMouseLeave={() => setIsPoseMenuOpen(false)}
            >
            <AnimatePresence>
                {isPoseMenuOpen && (
                    <motion.div
                        initial={{ opacity: 0, y: 10, scale: 0.95 }}
                        animate={{ opacity: 1, y: 0, scale: 1 }}
                        exit={{ opacity: 0, y: 10, scale: 0.95 }}
                        transition={{ duration: 0.2, ease: "easeOut" }}
                        className="absolute bottom-full mb-3 w-64 bg-white/80 backdrop-blur-lg rounded-xl p-2 border border-gray-200/80 shadow-lg"
                    >
                        <div className="grid grid-cols-2 gap-2">
                            {poseInstructions.map((pose, index) => (
                                <button
                                    key={pose}
                                    onClick={() => onSelectPose(index)}
                                    disabled={isLoading || index === currentPoseIndex}
                                    className="w-full text-left text-sm font-medium text-gray-800 p-2 rounded-md hover:bg-gray-200/70 disabled:opacity-50 disabled:bg-gray-200/70 disabled:font-bold disabled:cursor-not-allowed"
                                >
                                    {pose}
                                </button>
                            ))}
                        </div>
                    </motion.div>
                )}
            </AnimatePresence>

            <div className="flex items-center justify-center gap-2 bg-white/60 backdrop-blur-md rounded-full p-2 border border-gray-300/50 shadow-sm">
                <button 
                onClick={handlePreviousPose}
                aria-label="Previous pose"
                className="p-2 rounded-full hover:bg-white/80 active:scale-90 transition-all disabled:opacity-50"
                disabled={isLoading}
                >
                <ChevronLeftIcon className="w-5 h-5 text-gray-800" />
                </button>
                <span className="text-sm font-semibold text-gray-800 w-48 text-center truncate px-2" title={poseInstructions[currentPoseIndex]}>
                {poseInstructions[currentPoseIndex]}
                </span>
                <button 
                onClick={handleNextPose}
                aria-label="Next pose"
                className="p-2 rounded-full hover:bg-white/80 active:scale-90 transition-all disabled:opacity-50"
                disabled={isLoading}
                >
                <ChevronRightIcon className="w-5 h-5 text-gray-800" />
                </button>
            </div>
            </div>
        )}
      </div>
    </div>
  );
};

export default Canvas;

