        </div>
      </div>

      <div className="relative w-full h-full flex items-center justify-center">
        {displayImageUrl ? (
          <img src={displayImageUrl} alt="Model" className="max-w-full max-h-[80vh] object-contain rounded-[2rem] ios-shadow animate-zoom-in" />
