      </div>

      {/* Bottom Floating magic bar */}
      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 w-full max-w-lg px-4 space-y-4">
        <div className="ios-glass ios-shadow p-2 rounded-[2rem] flex items-center gap-2">
